#include "cuda/trellis35/reference.h"
#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cuda_fp8.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <string>
#include <utility>
#include "exllamav3_quant/util.cuh"
#include "exllamav3_quant/quant/codebook.cuh"

namespace gem16::internal {
namespace {
constexpr float kHadamardScale = 0.08838834764831845F;
#include "cuda/trellis35/detail/codec.cuh"
#include "cuda/trellis35/detail/mma_w4a8.cuh"
#include "cuda/trellis35/detail/h128_warp.cuh"
#include "trellis35_m1_eight_warp_candidate.cuh"

template <bool CaptureTransform>
__global__ void SelectedGateInputTransformQuantizeCandidateKernel(
    const float* input, const std::uint16_t* all_suh,
    const std::uint32_t* ids, std::uint8_t* quantized, float* scales,
    float* diagnostic_transform, unsigned assignments) {
  constexpr unsigned kWidth = 2816U;
  const unsigned assignment = blockIdx.x;
  if (assignment >= assignments) return;
  const unsigned expert = ids[assignment];
  if (expert >= 128U) return;
  input += static_cast<std::uint64_t>(assignment / 8U) * kWidth;
  all_suh += static_cast<std::uint64_t>(expert) * kWidth;
  quantized += static_cast<std::uint64_t>(assignment) * kWidth;
  __shared__ float transformed[kWidth];
  __shared__ float maxima[256];
  const unsigned warp = threadIdx.x >> 5U, lane = threadIdx.x & 31U;
  float maximum = 0.0F;
  for (unsigned block = warp; block < kWidth / 128U; block += 8U) {
    const unsigned base = block * 128U + lane * 4U;
    float values[4];
#pragma unroll
    for (unsigned i = 0U; i < 4U; ++i) values[i] = input[base + i] * F16(all_suh + base + i);
    H128Warp(values);
#pragma unroll
    for (unsigned i = 0U; i < 4U; ++i) {
      transformed[base + i] = values[i];
      maximum = fmaxf(maximum, fabsf(values[i]));
      if constexpr (CaptureTransform) diagnostic_transform[static_cast<std::uint64_t>(assignment) * kWidth + base + i] = values[i];
    }
  }
  maxima[threadIdx.x] = maximum;
  __syncthreads();
  for (unsigned stride = 128U; stride; stride >>= 1U) {
    if (threadIdx.x < stride) maxima[threadIdx.x] = fmaxf(maxima[threadIdx.x], maxima[threadIdx.x + stride]);
    __syncthreads();
  }
  const float scale = maxima[0] == 0.0F ? 1.0F : maxima[0] / 448.0F;
  if (threadIdx.x == 0U) scales[assignment] = scale;
  for (unsigned i = threadIdx.x; i < kWidth; i += blockDim.x) {
    const __nv_fp8_e4m3 encoded(transformed[i] / scale);
    quantized[i] = encoded.__x;
  }
}
}  // namespace
}  // namespace gem16::internal

extern "C" cudaError_t gem16_lab_launch_m1_eight(
    const std::uint8_t* activation, const float* scales,
    const gem16::internal::Trellis35DeviceFamilyBinding* family,
    const std::uint32_t* ids, float* output, std::uint64_t input_elements,
    std::uint64_t output_elements, cudaStream_t stream) {
  using namespace gem16::internal;
  MmaW4A8ProjectionSelectedN128EightWarpCandidateKernel<<<
      dim3(static_cast<unsigned>(output_elements / 128U), 8U), 256U, 0U, stream>>>(
          activation, scales, *family, ids, output, input_elements, output_elements);
  return cudaGetLastError();
}

extern "C" cudaError_t gem16_lab_launch_gate_fused(
    const float* input, const gem16::internal::Trellis35DeviceFamilyBinding* family,
    const std::uint32_t* ids, std::uint8_t* quantized, float* scales,
    float* diagnostic_transform, unsigned assignments, bool capture, cudaStream_t stream) {
  using namespace gem16::internal;
  if (capture) SelectedGateInputTransformQuantizeCandidateKernel<true><<<assignments, 256U, 0U, stream>>>(
      input, family->suh_f16, ids, quantized, scales, diagnostic_transform, assignments);
  else SelectedGateInputTransformQuantizeCandidateKernel<false><<<assignments, 256U, 0U, stream>>>(
      input, family->suh_f16, ids, quantized, scales, diagnostic_transform, assignments);
  return cudaGetLastError();
}

tests/cuda/trellis35_m1_eight_warp_candi.source:
// Unqualified test-only candidate. Included after the existing codec/MMA/H128
// helpers, so numerical boundaries stay shared with the measured parent.
template <int Rate>
__device__ __forceinline__ void AccumulateSelectedPairM1(
    const std::uint8_t* activation, const std::byte* pool,
    std::uint32_t pool_offset, std::uint64_t input_elements,
    std::uint64_t output_elements, std::uint64_t source_output,
    Fp8Accumulator& left, Fp8Accumulator& right) {
  constexpr unsigned kPrefetch = 4U;
  constexpr unsigned kPayloadWords = Rate * 256U / 32U;
  const unsigned lane = threadIdx.x & 31U;
  const unsigned quarter = lane & 3U;
  const auto* payload = reinterpret_cast<const std::uint32_t*>(pool + pool_offset);
  const auto tile_columns = output_elements / 16U;
  const auto output_tile = source_output / 16U;
  const unsigned position = TensorCoreIndex(quarter * 4U, static_cast<unsigned>(source_output & 15U));
  const unsigned iterations = static_cast<unsigned>(input_elements / 32U);
  auto load = [&](unsigned input_tile) {
    if (lane >= kPayloadWords) return std::uint32_t{0U};
    return payload[(static_cast<std::uint64_t>(input_tile) * tile_columns + output_tile) * kPayloadWords + lane];
  };
  std::uint32_t prefetched0[kPrefetch]{}, prefetched1[kPrefetch]{};
#pragma unroll
  for (unsigned depth = 0U; depth < kPrefetch; ++depth) {
    if (depth < iterations) {
      prefetched0[depth] = load(depth * 2U);
      prefetched1[depth] = load(depth * 2U + 1U);
    }
  }
  for (unsigned base = 0U; base < iterations; base += kPrefetch) {
#pragma unroll
    for (unsigned depth = 0U; depth < kPrefetch; ++depth) {
      const unsigned iteration = base + depth;
      if (iteration >= iterations) break;
      const auto word0 = prefetched0[depth], word1 = prefetched1[depth];
      if (iteration + kPrefetch < iterations) {
        prefetched0[depth] = load((iteration + kPrefetch) * 2U);
        prefetched1[depth] = load((iteration + kPrefetch) * 2U + 1U);
      }
      const auto first = static_cast<std::uint64_t>(iteration) * 32U + quarter * 4U;
      const auto a0 = *reinterpret_cast<const std::uint32_t*>(activation + first);
      const auto a1 = *reinterpret_cast<const std::uint32_t*>(activation + first + 16U);
      const auto b0 = DecodeLanePayloadSelectedE4M3x4<Rate, true>(word0, position);
      const auto b1 = DecodeLanePayloadSelectedE4M3x4<Rate, true>(word1, position);
      const auto c0 = DecodeLanePayloadSelectedE4M3x4<Rate, true>(word0, position + 4U);
      const auto c1 = DecodeLanePayloadSelectedE4M3x4<Rate, true>(word1, position + 4U);
      AccumulateFp8(a0, a1, b0, b1, left);
      AccumulateFp8(a0, a1, c0, c1, right);
    }
  }
}

__global__ void MmaW4A8ProjectionSelectedN128EightWarpCandidateKernel(
    const std::uint8_t* activation, const float* activation_scales,
    Trellis35DeviceFamilyBinding family, const std::uint32_t* selected_experts,
    float* output, std::uint64_t input_elements, std::uint64_t output_elements) {
  const unsigned slot = blockIdx.y, warp = threadIdx.x >> 5U, lane = threadIdx.x & 31U;
  const auto output_block = static_cast<std::uint64_t>(blockIdx.x) * 128U;
  const auto source = output_block + warp * 16U + (lane >> 2U);
  const auto expert = selected_experts[slot];
  if (expert >= kTrellis35ExpertCount) return;
  const auto descriptor = family.descriptors[expert];
  const auto* pool = descriptor.rate_bits == 3U ? family.k3_payload_pool : family.k4_payload_pool;
  activation += static_cast<std::uint64_t>(slot) * input_elements;
  output += static_cast<std::uint64_t>(slot) * output_elements;
  Fp8Accumulator left{}, right{};
  if (descriptor.rate_bits == 3U) {
    AccumulateSelectedPairM1<3>(activation, pool, descriptor.pool_offset,
                               input_elements, output_elements, source, left, right);
  } else {
    AccumulateSelectedPairM1<4>(activation, pool, descriptor.pool_offset,
                               input_elements, output_elements, source, left, right);
  }
  __shared__ float transformed[128];
  if (lane < 4U) {
    const unsigned i = warp * 16U + lane * 2U;
    const float scale = activation_scales[slot];
    transformed[i] = left.x0 * scale; transformed[i + 1U] = left.x1 * scale;
    transformed[i + 8U] = right.x0 * scale; transformed[i + 9U] = right.x1 * scale;
  }
  __syncthreads();
  if (warp == 0U) {
    const unsigned i = lane * 4U;
    float values[4]{transformed[i], transformed[i + 1U], transformed[i + 2U], transformed[i + 3U]};
    H128Warp(values);
    const auto* svh = family.svh_f16 + static_cast<std::uint64_t>(expert) * output_elements + output_block + i;
    const float4 packed{values[0] * F16(svh), values[1] * F16(svh + 1U),
                        values[2] * F16(svh + 2U), values[3] * F16(svh + 3U)};
    *reinterpret_cast<float4*>(output + output_block + i) = packed;
  }
}

tests/unit/decode_replay_test.cpp.source:
#include "../cuda/decode_replay_support.h"
#include "test.h"

#include <filesystem>
#include <fstream>
#include <string>
#include <string_view>

namespace {
void TestReplayInputValidation() {
  const auto root = std::filesystem::temp_directory_path() /
      ("gem16-decode-replay-" + std::to_string(
          decode_replay::Clock::now().time_since_epoch().count()));
  GEM16_CHECK(std::filesystem::create_directory(root));
  const auto input = root / "tokens.ids";
  auto fails = [](const auto& path, std::size_t count) {
    try { (void)decode_replay::ReadTokens(path, count); }
    catch (const std::exception&) { return true; }
    return false;
  };
  {
    std::ofstream file(input); file << " 0, 262143\n";
  }
  const auto tokens = decode_replay::ReadTokens(input, 2U);
  GEM16_CHECK(tokens.size() == 2U && tokens[0] == 0U && tokens[1] == 262143U);
  for (const std::string_view text : {
           "", "0,", "0,1,\n", "0,-1", "0,262144", "0,4294967296",
           "0,NaN", "0,1x", "0,1,2", "0"}) {
    { std::ofstream file(input, std::ios::trunc); file << text; }
    GEM16_CHECK(fails(input, 2U));
  }
  {
    std::ofstream file(input, std::ios::trunc);
    file << std::string(2U * 1024U * 1024U + 1U, '0');
  }
  GEM16_CHECK(fails(input, 2U));
  GEM16_CHECK(fails(root, 2U));
  GEM16_CHECK(fails(root / "missing", 2U));
  const auto link = root / "link.ids";
  std::error_code error;
  std::filesystem::create_symlink(input, link, error);
  if (!error) GEM16_CHECK(fails(link, 2U));
  std::filesystem::remove_all(root);
}
}  // namespace

void RunDecodeReplayTests() { TestReplayInputValidation(); }

